/**  Everything that changed under one workspace root during one debounce window. */
export type WorkspaceFileChanges = {
  /**  The root exactly as it was passed to the watcher. */
  root: string;
  /**  Worktree changes that pass the ignore rules, one entry per path. */
  changes: WorkspaceFileChange[];
  /**  Repository state (HEAD, the index, refs) changed; refresh the Git view. */
  git_changed: boolean;
  /**
   *  Events were lost or too many paths changed to list; `changes` may be incomplete and the
   *  whole root should be re-read.
   */
  rescan: boolean;
};

export type WorkspaceFileList = {
  files: string[];
  /**  Files matched in total, of which `files` is one page. */
  total: number;
  /**  Pass as `offset` for the next page; absent on the last page. */
  nextOffset: number | null;
  /**  The walk stopped early, so `total` is a lower bound. */
  truncated: boolean;
};

export type WorkspaceMatch = WorkspaceMatch_Serialize | WorkspaceMatch_Deserialize;

export type WorkspaceMatch_Deserialize = {
  path: string;
  line: number;
  text: string;
  before: string[];
  after: string[];
};

export type WorkspaceMatch_Serialize = {
  path: string;
  line: number;
  text: string;
  before?: string[];
  after?: string[];
};

/**
 *  One exact replacement of an agent edit. `old_text` must match exactly one location unless
 *  `replace_all` is set.
 */
export type WorkspaceReplacement = {
  oldText: string;
  newText: string;
  replaceAll?: boolean;
};

export type WorkspaceSearchResult =
  | WorkspaceSearchResult_Serialize
  | WorkspaceSearchResult_Deserialize;

export type WorkspaceSearchResult_Deserialize = {
  matches: WorkspaceMatch_Deserialize[];
  /**  Some matches were left out: the result cap, a per-file cap, or the walk limit was hit. */
  truncated: boolean;
  filesSearched: number;
};

export type WorkspaceSearchResult_Serialize = {
  matches: WorkspaceMatch_Serialize[];
  /**  Some matches were left out: the result cap, a per-file cap, or the walk limit was hit. */
  truncated: boolean;
  filesSearched: number;
};

export type WslDistribution = {
  name: string;
  state: string | null;
  version: number | null;
  is_default: boolean;
};

export type WslFileEntry = {
  name: string;
  path: string;
  is_dir: boolean;
  size: number;
  is_symlink: boolean;
  target: string | null;
};

export type WslSymlinkInfo = {
  is_symlink: boolean;
  target: string | null;
  is_dir: boolean;
};
